/**
 * Reviewing by reading the notebook (§9 `notebook.browse`): how long the
 * notebook was on screen, how many of its words were on screen, how many
 * were opened or heard, how many searches were made and how many found
 * nothing. Counts only: never which words, never the query.
 *
 * Truthful (§10): time counts only while somebody is here (`presence.ts`);
 * a row counts as seen once per app session, after at least `SEEN_MS` with
 * at least `SEEN_SHARE` of it showing while somebody is here, so a fast
 * scroll past it never counts.
 *
 * Built so the list does not pay for it: one shared IntersectionObserver
 * (the browser reports crossings off the scroll path), and each report is a
 * map write. Nothing runs per scroll or per frame, and nothing renders.
 */
import { activityOn, onActivityGate, signal } from '@/lib/surface.js';
import { isPresent, onPresence } from './presence.js';

/** How long a row must be on screen to count as seen (§10: "≥1 s"). */
export const SEEN_MS = 1_000;
/** The share of a row that must show for it to be on screen (§10: "≥50%"). */
export const SEEN_SHARE = 0.5;

interface Browse {
  /** Present time so far, and when the present stretch began (undefined while nobody is here). */
  ms: number;
  since: number | undefined;
  /** Rows first seen in this report. */
  seen: number;
  opened: number;
  audio: number;
  searches: number;
  searchesEmpty: number;
}

let browse: Browse | undefined;
/** When each row on screen began its present stretch on screen. */
const onScreen = new Map<string, number | undefined>();
/** Rows already counted in this app session (§10: once per app session). */
let seenThisSession = new Set<string>();
const rowOf = new WeakMap<Element, string>();
let observer: IntersectionObserver | undefined;
let offPresence: (() => void) | undefined;

function observe(): IntersectionObserver | undefined {
  if (observer !== undefined || typeof IntersectionObserver === 'undefined') return observer;
  observer = new IntersectionObserver(
    (entries) => {
      const now = Date.now();
      for (const entry of entries) {
        const id = rowOf.get(entry.target);
        if (id === undefined) continue;
        if (entry.isIntersecting && entry.intersectionRatio >= SEEN_SHARE) {
          if (!onScreen.has(id)) onScreen.set(id, isPresent() ? now : undefined);
        } else {
          settleRow(id, now);
          onScreen.delete(id);
        }
      }
    },
    { threshold: [0, SEEN_SHARE] },
  );
  return observer;
}

/** Counts a row whose present stretch reached `SEEN_MS` by `at`; it stays on screen. */
function settleRow(id: string, at: number): void {
  const from = onScreen.get(id);
  if (from === undefined || browse === undefined) return;
  if (at - from >= SEEN_MS && !seenThisSession.has(id)) {
    seenThisSession.add(id);
    browse.seen += 1;
  }
}

/** A row of the notebook's list: watched while the notebook is browsed. Returns the way to stop. */
export function watchRow(element: Element, wordId: string): () => void {
  // Kept in a plain list whatever the switch, so rows already on screen are
  // watched the moment it comes on; observed only while it is on.
  rows.set(element, wordId);
  rowOf.set(element, wordId);
  followGate();
  if (activityOn()) observe()?.observe(element);
  return () => {
    rows.delete(element);
    observer?.unobserve(element);
    settleRow(wordId, Date.now());
    onScreen.delete(wordId);
  };
}

/** The rows of the list on screen now (only their elements and ids). */
const rows = new Map<Element, string>();
/** Whether a notebook screen asked for a browse (it starts once the switch is on). */
let wanted = false;
let offGate: (() => void) | undefined;

/** Follows the switch: on, the rows are watched and a wanted browse starts; off, all of it stops. */
function followGate(): void {
  offGate ??= onActivityGate((on) => {
    if (on) {
      const io = observe();
      for (const element of rows.keys()) io?.observe(element);
      if (wanted && browse === undefined) begin(Date.now());
    } else {
      flushBrowse();
      browse = undefined;
      offPresence?.();
      offPresence = undefined;
      observer?.disconnect();
      observer = undefined;
      onScreen.clear();
    }
  });
}

function presenceChanged(here: boolean, at: number): void {
  if (browse === undefined) return;
  if (here) {
    browse.since = at;
    for (const id of onScreen.keys()) onScreen.set(id, at);
  } else {
    if (browse.since !== undefined) browse.ms += Math.max(0, at - browse.since);
    browse.since = undefined;
    for (const id of onScreen.keys()) {
      settleRow(id, at);
      onScreen.set(id, undefined);
    }
  }
}

function fresh(now: number): Browse {
  return {
    ms: 0,
    since: isPresent() ? now : undefined,
    seen: 0,
    opened: 0,
    audio: 0,
    searches: 0,
    searchesEmpty: 0,
  };
}

/** The notebook screen opened (or its notebook changed). */
export function startBrowse(now: number = Date.now()): void {
  if (browse !== undefined) flushBrowse(now);
  wanted = true;
  followGate();
  // Nothing at all runs while the server does not take the events (no
  // presence ticker, no observer): the switch off is the app as it was.
  if (!activityOn()) return;
  begin(now);
}

function begin(now: number): void {
  offPresence ??= onPresence(presenceChanged);
  browse = fresh(now);
  // Rows already on screen start counting from now.
  for (const id of onScreen.keys()) onScreen.set(id, browse.since);
}

/** The notebook screen went away: what it counted is sent. */
export function stopBrowse(now: number = Date.now()): void {
  wanted = false;
  flushBrowse(now);
  browse = undefined;
  offPresence?.();
  offPresence = undefined;
}

export function noteOpened(): void {
  if (browse !== undefined) browse.opened += 1;
}

export function noteAudio(): void {
  if (browse !== undefined) browse.audio += 1;
}

/** A search that settled; `empty` when it found nothing. */
export function noteSearch(empty: boolean): void {
  if (browse === undefined) return;
  browse.searches += 1;
  if (empty) browse.searchesEmpty += 1;
}

/** A new app session began (`events.ts`): every row may be seen again. */
export function newBrowseSession(): void {
  seenThisSession = new Set();
}

/**
 * Sends what was counted (the app going to the background, the screen
 * closing) and goes on counting the same browse from nothing.
 */
export function flushBrowse(now: number = Date.now()): void {
  const b = browse;
  if (b === undefined) return;
  for (const id of onScreen.keys()) settleRow(id, now);
  const ms = b.ms + (b.since === undefined ? 0 : Math.max(0, now - b.since));
  const seconds = Math.round(ms / 1000);
  if (seconds >= 1) {
    signal(
      {
        name: 'notebook.browse',
        surface: 'app.notebook',
        meta: {
          seconds,
          wordsSeen: b.seen,
          wordsOpened: b.opened,
          audioPlayed: b.audio,
          searches: b.searches,
          searchesEmpty: b.searchesEmpty,
        },
      },
      now,
    );
  }
  browse = { ...fresh(now), since: b.since === undefined ? undefined : now };
  // A row already counted stays counted; one still on screen keeps its start.
}

/** For tests. */
export function __resetBrowseForTests(): void {
  browse = undefined;
  wanted = false;
  rows.clear();
  offGate?.();
  offGate = undefined;
  onScreen.clear();
  seenThisSession = new Set();
  observer?.disconnect();
  observer = undefined;
  offPresence?.();
  offPresence = undefined;
}
