/**
 * Whether somebody is here (§10 "measurement truthfulness"): the page is
 * shown **and** has the focus (or is a phone app in the foreground, where
 * the web view holds the focus). Time counts only then.
 *
 * A laptop that sleeps with the page shown fires no event, so a clock read
 * after waking would count the whole night. A light tick (`TICK_MS`, only
 * while present) notes that the page is alive; a gap longer than
 * `SLEEP_GAP_MS` between ticks means the device was asleep, and time is
 * counted only up to the last tick (`aliveNow`).
 */

export const TICK_MS = 15_000;
export const SLEEP_GAP_MS = 45_000;

type Listener = (present: boolean, at: number) => void;

let lastAlive = Date.now();
let present = false;
let timer: ReturnType<typeof setInterval> | undefined;
const listeners = new Set<Listener>();

function hereNow(): boolean {
  if (document.visibilityState === 'hidden') return false;
  return typeof document.hasFocus !== 'function' || document.hasFocus();
}

/** The moment to count up to: now, or the last tick before a sleep. */
export function aliveNow(now: number = Date.now()): number {
  return now - lastAlive > SLEEP_GAP_MS ? lastAlive : now;
}

export function isPresent(): boolean {
  return present;
}

function update(): void {
  const now = Date.now();
  const at = aliveNow(now);
  const next = hereNow();
  if (next === present) {
    if (next && at !== now) {
      // Woke from a sleep while shown: the time asleep ends here, the time
      // awake starts now.
      for (const listener of listeners) listener(false, at);
      lastAlive = now;
      for (const listener of listeners) listener(true, now);
    }
    lastAlive = now;
    return;
  }
  present = next;
  for (const listener of listeners) listener(next, next ? now : at);
  lastAlive = now;
}

/** Hears presence change, with the moment it changed; returns the way to stop. */
export function onPresence(listener: Listener): () => void {
  listeners.add(listener);
  if (listeners.size === 1) start();
  return () => {
    listeners.delete(listener);
    if (listeners.size === 0) stop();
  };
}

const events = ['visibilitychange', 'focus', 'blur', 'pageshow', 'pagehide'] as const;

function start(): void {
  present = hereNow();
  lastAlive = Date.now();
  document.addEventListener('visibilitychange', update);
  for (const name of events) if (name !== 'visibilitychange') window.addEventListener(name, update);
  timer = setInterval(() => {
    if (present || hereNow()) update();
  }, TICK_MS);
}

function stop(): void {
  document.removeEventListener('visibilitychange', update);
  for (const name of events) if (name !== 'visibilitychange') window.removeEventListener(name, update);
  clearInterval(timer);
  timer = undefined;
}

/** For tests: read the page again now, as a tick would. */
export function __tickForTests(): void {
  update();
}
